        V(mutex);
        V(Sb);                  //B 比 A 可多的额度增加 1
    }
}
process_B() {
    while (1) {
        P(Sb);                  //B 还可入库一个，保证 B-A < N
        P(mutex);               //互斥访问仓库
        B产品入库;
        V(mutex);
        V(Sa);                  //A 比 B 可多的额度增加 1
    }
}
