【解答】 顾客进店后按序取号，并等待叫号；销售人员空闲后也按序叫号，并销售面包。因此同步算法只要对顾客取号和销售人员叫号进行合理同步即可。我们使用两个变量 i 和 j 分别记录当前的取号值和叫号值，并各自使用一个互斥信号量用于对 i 和 j 进行访问和修改。
int i=0, j=0;
semaphore mutex_i=1, mutex_j=1;
//顾客
Consumer() {
    进入面包店；
    P(mutex_i);             //互斥访问 i
    取号，取到的号码为 i；
    i++;
    V(mutex_i);             //释放对 i 的访问
    等待叫号并购买面包；
}
//销售人员
Seller() {
    while (1) {
        P(mutex_j);         //互斥访问 j
        if (j < i) {        //已有顾客取号并等待叫号
            叫 j 号；
            j++;
            V(mutex_j);     //释放对 j 的访问
            销售面包；
        } else {            //暂时没有顾客在等待
            V(mutex_j);     //释放对 j 的访问
            休息片刻；
        }
    }
}
